content:
:root {
  --primary: #6366f1;
  --primary-hover: #4f46e5;
  --primary-light: #e0e7ff;
  --bg-gradient: linear-gradient(135deg, #f5f7fb 0%, #e8edf5 100%);
  --surface: #ffffff;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --border-color: #e2e8f0;
  --danger: #ef4444;
  --danger-hover: #dc2626;
  --danger-light: #fee2e2;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.08), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
  --shadow-lg: 0 10px 25px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.04);
  --font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Hiragino Sans', 'Noto Sans JP', sans-serif;
  --transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background: var(--bg-gradient);
  color: var(--text-main);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 40px 16px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

#root {
  width: 100%;
  max-width: 580px;
}

/* キーボードフォーカス時の共通スタイル */
button:focus-visible,
input:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: 2px;
}

/* アプリ全体コンテナ */
.todo-app {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* ヘッダーエリア */
.header {
  text-align: center;
  margin-bottom: 4px;
}

.title {
  font-size: 2rem;
  font-weight: 800;
  letter-spacing: -0.025em;
  color: #1e1b4b;
  margin-bottom: 6px;
}

.subtitle {
  font-size: 0.95rem;
  color: var(--text-muted);
}

/* メインカード */
.card {
  background: var(--surface);
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow-lg);
  border: 1px solid rgba(255, 255, 255, 0.8);
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* タスク入力フォーム */
.input-form {
  display: flex;
  gap: 10px;
  width: 100%;
}

.todo-input {
  flex: 1;
  padding: 12px 16px;
  font-size: 0.975rem;
  font-family: inherit;
  color: var(--text-main);
  background-color: #f8fafc;
  border: 1.5px solid var(--border-color);
  border-radius: var(--radius-md);
  outline: none;
  transition: var(--transition);
}

.todo-input::placeholder {
  color: #94a3b8;
}

.todo-input:focus {
  background-color: #ffffff;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.15);
}

.todo-input:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: 1px;
}

.add-button {
  background: var(--primary);
  color: #ffffff;
  border: none;
  padding: 12px 20px;
  font-size: 0.95rem;
  font-weight: 600;
  border-radius: var(--radius-md);
  cursor: pointer;
  white-space: nowrap;
  transition: var(--transition);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
}

.add-button:hover {
  background: var(--primary-hover);
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(99, 102, 241, 0.3);
}

.add-button:active {
  transform: translateY(0);
}

.add-button:focus-visible {
  outline: 2px solid var(--primary-hover);
  outline-offset: 2px;
}

/* フィルタータブ */
.filter-tabs {
  display: flex;
  background-color: #f1f5f9;
  padding: 4px;
  border-radius: var(--radius-md);
  gap: 4px;
}

.filter-button {
  flex: 1;
  background: transparent;
  border: none;
  padding: 8px 12px;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-muted);
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: var(--transition);
  text-align: center;
}

.filter-button:hover {
  color: var(--text-main);
}

.filter-button.active {
  background: var(--surface);
  color: var(--primary);
  font-weight: 600;
  box-shadow: var(--shadow-sm);
}

.filter-button:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: 2px;
}

/* 統計・ステータス表示バー */
.todo-stats {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.875rem;
  color: var(--text-muted);
  padding: 0 4px;
}

.todo-stats button {
  background: none;
  border: none;
  color: var(--text-muted);
  font-size: 0.825rem;
  cursor: pointer;
  padding: 4px 8px;
  border-radius: var(--radius-sm);
  transition: var(--transition);
}

.todo-stats button:hover {
  color: var(--danger);
  background: var(--danger-light);
}

.todo-stats button:focus-visible {
  outline: 2px solid var(--danger);
  outline-offset: 2px;
}

/* タスク一覧リスト */
.todo-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin: 0;
  padding: 0;
  max-height: 400px;
  overflow-y: auto;
  padding-right: 4px;
}

/* タスクリスト用モダンカスタムスクロールバー */
.todo-list::-webkit-scrollbar {
  width: 6px;
}

.todo-list::-webkit-scrollbar-track {
  background: transparent;
}

.todo-list::-webkit-scrollbar-thumb {
  background: #cbd5e1;
  border-radius: 9999px;
}

.todo-list::-webkit-scrollbar-thumb:hover {
  background: #94a3b8;
}

/* 個別タスクアイテム */
.todo-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px;
  background: #f8fafc;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  gap: 12px;
  transition: var(--transition);
}

.todo-item:hover {
  background: #ffffff;
  border-color: #cbd5e1;
  box-shadow: var(--shadow-sm);
  transform: translateY(-1px);
}

.todo-item.completed {
  background: #f8fafc;
  opacity: 0.75;
}

.todo-item.completed .todo-text {
  text-decoration: line-through;
  color: #94a3b8;
}

/* チェックボックスとテキスト */
.checkbox-label {
  display: flex;
  align-items: center;
  gap: 12px;
  flex: 1;
  cursor: pointer;
  user-select: none;
  min-width: 0;
}

.todo-checkbox {
  appearance: none;
  -webkit-appearance: none;
  width: 20px;
  height: 20px;
  border: 2px solid #cbd5e1;
  border-radius: 6px;
  outline: none;
  cursor: pointer;
  transition: background-color 0.2s cubic-bezier(0.4, 0, 0.2, 1), border-color 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  position: relative;
  flex-shrink: 0;
  background-color: #ffffff;
}

.todo-checkbox:hover {
  border-color: var(--primary);
}

.todo-checkbox:checked {
  background-color: var(--primary);
  border-color: var(--primary);
}

.todo-checkbox:checked::after {
  content: '';
  position: absolute;
  top: 2px;
  left: 6px;
  width: 5px;
  height: 10px;
  border: solid #ffffff;
  border-width: 0 2px 2px 0;
  transform: rotate(45deg);
}

.todo-checkbox:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: 2px;
}

.todo-text {
  font-size: 0.95rem;
  color: var(--text-main);
  word-break: break-word;
  transition: color 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  line-height: 1.4;
}

/* 削除ボタン */
.delete-button {
  background: transparent;
  color: #94a3b8;
  border: none;
  width: 32px;
  height: 32px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition: var(--transition);
}

.delete-button:hover {
  color: var(--danger);
  background-color: var(--danger-light);
}

.delete-button:focus-visible {
  outline: 2px solid var(--danger);
  outline-offset: 2px;
}

/* タスク空状態 */
.empty-state {
  text-align: center;
  padding: 40px 16px;
  color: var(--text-muted);
  font-size: 0.925rem;
  background: #f8fafc;
  border: 1.5px dashed var(--border-color);
  border-radius: var(--radius-md);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
}

/* レスポンシブ対応 */
@media (max-width: 480px) {
  body {
    padding: 20px 12px;
  }

  .card {
    padding: 16px;
    gap: 16px;
  }

  .title {
    font-size: 1.6rem;
  }

  .todo-input {
    padding: 10px 12px;
    font-size: 0.9rem;
  }

  .add-button {
    padding: 10px 16px;
    font-size: 0.9rem;
  }

  .todo-item {
    padding: 12px;
  }
}

export interface TodoItem {
  id: string;
  text: string;
  completed: boolean;
  createdAt: string;
}

export type NewTodoPayload = Omit<TodoItem, 'id' | 'createdAt'>;

export const FILTER_OPTIONS = ['all', 'active', 'completed'] as const;

export type FilterStatus = (typeof FILTER_OPTIONS)[number];

import { useState, type FormEvent, type ChangeEvent } from 'react';
import { Plus } from 'lucide-react';

interface TodoInputProps {
  onAdd: (text: string) => void;
}

const TodoInput = ({ onAdd }: TodoInputProps) => {
  const [inputText, setInputText] = useState('');

  const handleSubmit = (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const trimmed = inputText.trim();
    if (!trimmed) {
      return;
    }
    onAdd?.(trimmed);
    setInputText('');
  };

  const handleChange = (e: ChangeEvent<HTMLInputElement>) => {
    setInputText(e.target.value);
  };

  const isInputEmpty = !inputText.trim();

  return (
    <form className="input-form" onSubmit={handleSubmit}>
      <input
        type="text"
        className="todo-input"
        placeholder="新しいタスクを入力してください..."
        aria-label="新しいタスク"
        value={inputText}
        onChange={handleChange}
        autoFocus
      />
      <button
        type="submit"
        className="add-button"
        aria-label="タスクを追加"
        disabled={isInputEmpty}
        style={{
          opacity: isInputEmpty ? 0.5 : 1,
          cursor: isInputEmpty ? 'not-allowed' : 'pointer',
        }}
      >
        <Plus size={18} />
        <span>追加</span>
      </button>
    </form>
  );
};

export default TodoInput;

import { Trash2, ClipboardList } from 'lucide-react';
import type { TodoItem } from '../types';

interface TodoListProps {
  todos?: TodoItem[];
  onToggle: (id: string) => void;
  onDelete: (id: string) => void;
}

const formatDate = (dateString?: string) => {
  if (!dateString) return '';
  try {
    const date = new Date(dateString);
    if (isNaN(date.getTime())) return '';
    return date.toLocaleDateString('ja-JP', {
      month: 'numeric',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  } catch {
    return '';
  }
};

const TodoList = ({ todos = [], onToggle, onDelete }: TodoListProps) => {
  if (todos.length === 0) {
    return (
      <div className="empty-state">
        <ClipboardList size={36} color="var(--text-muted)" strokeWidth={1.5} />
        <p>該当するタスクはありません</p>
      </div>
    );
  }

  return (
    <ul className="todo-list">
      {todos.map((todo) => {
        const itemClass = todo.completed ? 'todo-item completed' : 'todo-item';
        const formattedDate = formatDate(todo.createdAt);

        return (
          <li key={todo.id} className={itemClass}>
            <label className="checkbox-label">
              <input
                type="checkbox"
                className="todo-checkbox"
                checked={todo.completed}
                onChange={() => onToggle?.(todo.id)}
              />
              <span style={{ display: 'flex', flexDirection: 'column', minWidth: 0 }}>
                <span className="todo-text">{todo.text}</span>
                {formattedDate && (
                  <time
                    dateTime={todo.createdAt}
                    style={{ fontSize: '0.75rem', color: 'var(--text-muted)', marginTop: '2px' }}
                  >
                    作成: {formattedDate}
                  </time>
                )}
              </span>
            </label>
            <button
              type="button"
              className="delete-button"
              onClick={() => onDelete?.(todo.id)}
              aria-label={`タスク「${todo.text}」を削除`}
              title="削除"
            >
              <Trash2 size={16} />
            </button>
          </li>
        );
      })}
    </ul>
  );
};

export default TodoList;

import { useState, useEffect } from 'react';
import { FILTER_OPTIONS, type TodoItem, type FilterStatus } from './types';
import TodoInput from './components/TodoInput';
import TodoList from './components/TodoList';

const STORAGE_KEY = 'todo_app_tasks';

const INITIAL_TODOS: TodoItem[] = [
  {
    id: '1',
    text: '企画書のドラフト作成と見直し',
    completed: false,
    createdAt: new Date().toISOString(),
  },
  {
    id: '2',
    text: 'チームミーティングの議事録共有',
    completed: true,
    createdAt: new Date().toISOString(),
  },
  {
    id: '3',
    text: 'デザインカンプのレビュー確認',
    completed: false,
    createdAt: new Date().toISOString(),
  },
  {
    id: '4',
    text: '参考資料の整理とアーカイブ',
    completed: true,
    createdAt: new Date().toISOString(),
  },
];

const FILTER_LABELS: Record<FilterStatus, string> = {
  all: 'すべて',
  active: '未完了',
  completed: '完了済み',
};

const App = () => {
  const [todos, setTodos] = useState<TodoItem[]>(() => {
    try {
      const savedTodos = localStorage.getItem(STORAGE_KEY);
      if (savedTodos) {
        return JSON.parse(savedTodos) as TodoItem[];
      }
    } catch {
      // localStorageへのアクセスエラー時のフォールバック
    }
    return INITIAL_TODOS;
  });

  const [filter, setFilter] = useState<FilterStatus>('all');

  useEffect(() => {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
    } catch {
      // localStorageへの保存エラー時の処理
    }
  }, [todos]);

  const handleAddTodo = (text: string) => {
    const newTodo: TodoItem = {
      id: crypto.randomUUID(),
      text,
      completed: false,
      createdAt: new Date().toISOString(),
    };
    setTodos((prev) => [newTodo, ...prev]);
  };

  const handleToggleTodo = (id: string) => {
    setTodos((prev) =>
      prev.map((todo) =>
        todo.id === id ? { ...todo, completed: !todo.completed } : todo
      )
    );
  };

  const handleDeleteTodo = (id: string) => {
    setTodos((prev) => prev.filter((todo) => todo.id !== id));
  };

  const handleClearCompleted = () => {
    setTodos((prev) => prev.filter((todo) => !todo.completed));
  };

  const filteredTodos = todos.filter((todo) => {
    if (filter === 'active') {
      return !todo.completed;
    }
    if (filter === 'completed') {
      return todo.completed;
    }
    return true;
  });

  const activeCount = todos.filter((todo) => !todo.completed).length;
  const completedCount = todos.filter((todo) => todo.completed).length;

  const filterCounts: Record<FilterStatus, number> = {
    all: todos.length,
    active: activeCount,
    completed: completedCount,
  };

  return (
    <div className="todo-app">
      <header className="header">
        <h1 className="title">やることリスト</h1>
        <p className="subtitle">日々のタスクをすっきり整理して生産性を向上させましょう</p>
      </header>

      <main className="card">
        <TodoInput onAdd={handleAddTodo} />

        <div className="filter-tabs" role="tablist">
          {FILTER_OPTIONS.map((status) => (
            <button
              key={status}
              type="button"
              role="tab"
              aria-selected={filter === status}
              className={filter === status ? 'filter-button active' : 'filter-button'}
              onClick={() => setFilter(status)}
            >
              {FILTER_LABELS[status]} ({filterCounts[status]})
            </button>
          ))}
        </div>

        <TodoList
          todos={filteredTodos}
          onToggle={handleToggleTodo}
          onDelete={handleDeleteTodo}
        />

        <div className="todo-stats">
          <span>未完了タスク: {activeCount}件</span>
          {completedCount > 0 && (
            <button type="button" onClick={handleClearCompleted}>
              完了済みを一括削除
            </button>
          )}
        </div>
      </main>
    </div>
  );
};

export default App;
